function validate([root, k]) {
  const values = root.filter(v => v !== null);
  if (values.length < 1 || values.length > 2000) return 'The tree has 1 to 2000 nodes.';
  if (values.some(v => v < 1 || v > 2000)) return 'Node values are between 1 and 2000.';
  if (!Number.isInteger(k) || k < 1 || k > 1024) return 'k is between 1 and 1024.';
  return null;
}

