function kthLargestPerfectSubtree(root, k) {
  const sizes = [];

  // Size of the perfect subtree rooted at node: 0 for no node, -1 if it is not perfect.
  const dfs = (node) => {
    if (node === null) {
      return 0;
    }
    const left = dfs(node.left);
    const right = dfs(node.right);
    if (left === -1 || left !== right) {
      return -1;
    }
    const size = left + right + 1;
    sizes.push(size);
    return size;
  };

  dfs(root);
  sizes.sort((a, b) => b - a);
  return k <= sizes.length ? sizes[k - 1] : -1;
}

