function kthLargestPerfectSubtree(root, k) {
  const everyNode = [];
  const collect = (node) => { if (!node) return; everyNode.push(node); collect(node.left); collect(node.right); };
  collect(root);
  const sizes = [];
  // Check the definition directly on every subtree: 0 or 2 children everywhere, one depth for all leaves.
  for (const top of everyNode) {
    let perfect = true, leafDepth = -1, count = 0;
    const stack = [[top, 0]];
    while (stack.length) {
      const [node, depth] = stack.pop();
      count++;
      const children = (node.left ? 1 : 0) + (node.right ? 1 : 0);
      if (children === 1) perfect = false;
      if (children === 0) {
        if (leafDepth === -1) leafDepth = depth;
        else if (leafDepth !== depth) perfect = false;
      }
      if (node.left) stack.push([node.left, depth + 1]);
      if (node.right) stack.push([node.right, depth + 1]);
    }
    if (perfect) sizes.push(count);
  }
  sizes.sort((a, b) => b - a);
  return sizes.length >= k ? sizes[k - 1] : -1;
}

