function generate(rand, size) {
  const large = size === 'large';
  const val = () => 1 + Math.floor(rand() * (large ? 2000 : 9));
  let budget = 0;
  const both = large ? 0.4 + rand() * 0.3 : 0.2 + rand() * 0.5;
  const blocks = large ? 0.12 : 0.2;
  // A perfect block of height h (cut short if the node budget runs out).
  const perfect = (h) => {
    if (h === 0 || budget <= 0) return null;
    budget--;
    return { val: val(), left: perfect(h - 1), right: perfect(h - 1) };
  };
  // A random shape: each node grows two, one or no children, and some branches end in a perfect block.
  const grow = () => {
    if (budget <= 0) return null;
    if (rand() < blocks) return perfect(1 + Math.floor(rand() * (large ? 7 : 3)));
    budget--;
    const node = { val: val(), left: null, right: null };
    const roll = rand();
    if (roll < both) { node.left = grow(); node.right = grow(); }
    else if (roll < both + (1 - both) * 0.45) node.left = grow();
    else if (roll < both + (1 - both) * 0.9) node.right = grow();
    return node;
  };
  // A long spine; beside each spine node hangs nothing or a small perfect block.
  const spine = () => {
    const top = { val: val(), left: null, right: null };
    budget--;
    let tip = top;
    while (budget > 0) {
      const next = { val: val(), left: null, right: null };
      budget--;
      const hang = rand() < 0.5 ? null : perfect(1 + Math.floor(rand() * 3));
      if (rand() < 0.5) { tip.left = next; tip.right = hang; } else { tip.right = next; tip.left = hang; }
      tip = next;
    }
    return top;
  };
  const useSpine = large && rand() < 0.35;
  let root;
  // A large tree is rebuilt until it has used most of its node budget.
  do {
    budget = large ? 1900 : 1 + Math.floor(rand() * 15);
    root = useSpine ? spine() : grow();
  } while (large && budget > 400);
  // Level order with null for missing children; any prefix of it is still a valid tree.
  const values = [];
  const queue = [root];
  for (let i = 0; i < queue.length && values.length < 2000; i++) {
    const node = queue[i];
    values.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (values[values.length - 1] === null) values.pop();
  const count = values.filter(v => v !== null).length;
  let k;
  if (large) k = rand() < 0.5 ? 1 + Math.floor(rand() * 8) : 1 + Math.floor(rand() ** 2 * 1024);
  else k = 1 + Math.floor(rand() ** 2 * (count + 1));
  return [values, k];
}
